argv:
$ErrorActionPreference='Stop'
$t=Invoke-RestMethod -UseBasicParsing 'http://127.0.0.1:17410/json/list' -TimeoutSec 3
$target=@($t)|Where-Object { try { ([uri]$_.url).Host -eq 'bugbountyfoto6.files.com' } catch { $false } } | Select-Object -First 1
$ws=[Net.WebSockets.ClientWebSocket]::new();$cts=[Threading.CancellationTokenSource]::new();$cts.CancelAfter(8000)
$ws.ConnectAsync([uri]$target.webSocketDebuggerUrl,$cts.Token).GetAwaiter().GetResult()|Out-Null
$expr=@'
(async()=>{
 const d=[...document.querySelectorAll('[role="dialog"]')].find(x=>(x.innerText||'').includes('New folder'));
 if(!d) return JSON.stringify({error:'New folder dialog not found'});
 const input=d.querySelector('input[name="name"]');
 const create=[...d.querySelectorAll('button')].find(b=>(b.innerText||'').trim()==='Create');
 if(!input||!create) return JSON.stringify({error:'form controls missing'});
 const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
 setter.call(input,'authz-probe-20260930');
 input.dispatchEvent(new Event('input',{bubbles:true}));
 input.dispatchEvent(new Event('change',{bubbles:true}));
 await new Promise(r=>setTimeout(r,100));
 create.click();
 await new Promise(r=>setTimeout(r,1200));
 return JSON.stringify({
   path:location.pathname,
   exists:[...document.querySelectorAll('a')].some(a=>(a.textContent||'').trim()==='authz-probe-20260930'),
   body:(document.body.innerText||'').includes('authz-probe-20260930')
 });
})()
'@
$payload=@{id=1;method='Runtime.evaluate';params=@{expression=$expr;returnByValue=$true;awaitPromise=$true}}|ConvertTo-Json -Depth 10 -Compress
$bytes=[Text.Encoding]::UTF8.GetBytes($payload)
$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,$cts.Token).GetAwaiter().GetResult()|Out-Null
$buf=New-Object byte[] 131072
while($true){$ms=[IO.MemoryStream]::new();do{$r=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),$cts.Token).GetAwaiter().GetResult();if($r.Count){$ms.Write($buf,0,$r.Count)}}while(-not $r.EndOfMessage);$o=([Text.Encoding]::UTF8.GetString($ms.ToArray())|ConvertFrom-Json);if($o.id -eq 1){if($o.result.exceptionDetails){throw $o.result.exceptionDetails.text};Write-Output $o.result.result.value;break}}
$ws.Dispose()
